-- Representative original Phase 2 content for OCR GCSE.
-- This is intentionally a sample learning path, not a complete specification.

-- Ensure the referenced course shells exist when migrations run before seed.sql.
on conflict do nothing;
on conflict do nothing;
on conflict do nothing;

on conflict (course_id, code) do update set title=excluded.title, description=excluded.description, status='published';

on conflict (specification_section_id, slug) do update set title=excluded.title, description=excluded.description, learning_objectives=excluded.learning_objectives, status='published';

on conflict (topic_id, slug) do update set title=excluded.title, description=excluded.description, status='published';

on conflict (subtopic_id, slug) do update set title=excluded.title, summary=excluded.summary, status='published';

on conflict (id) do update set heading=excluded.heading, body=excluded.body, sort_order=excluded.sort_order;

on conflict (id) do update set front=excluded.front, back=excluded.back, hint=excluded.hint, status='published';

on conflict (id) do update set title=excluded.title, prompt=excluded.prompt, steps=excluded.steps, final_answer=excluded.final_answer, status='published';
