insert into public.topics (id, specification_section_id, slug, title, description, icon, estimated_minutes, learning_objectives, sort_order, status) values
  ('20000000-0000-0000-0000-000000000001','11000000-0000-0000-0000-000000000001','systems-architecture','Systems architecture','Discover how the CPU carries out instructions and how its components work together.','🧩',35,array['Describe the purpose of the CPU and its main components','Explain the fetch–decode–execute cycle','Compare factors that affect CPU performance'],1,'published'),
  ('20000000-0000-0000-0000-000000000002','11000000-0000-0000-0000-000000000001','memory-and-storage','Memory and storage','Compare primary memory, secondary storage and the units used to measure data.','💾',42,array['Compare RAM and ROM','Explain why virtual memory is used','Select suitable storage for a given situation'],2,'published'),
  ('20000000-0000-0000-0000-000000000003','11000000-0000-0000-0000-000000000001','networks-and-protocols','Networks and protocols','Explore network types, topologies, packet switching and the rules that keep communication reliable.','🌐',38,array['Distinguish LANs and WANs','Describe packet switching','Explain the roles of common protocols'],3,'published')
insert into public.subtopics (id, topic_id, slug, title, description, sort_order, status) values
  ('21000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','central-processing-unit','The central processing unit','CPU components, registers and instruction processing.',1,'published'),
  ('21000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','memory-and-secondary-storage','Memory and secondary storage','How computers hold active and persistent data.',1,'published'),
  ('21000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000003','connections-and-communication','Connections and communication','How networked devices exchange data.',1,'published')
insert into public.lessons (id, subtopic_id, slug, title, summary, estimated_minutes, sort_order, status) values
  ('30000000-0000-0000-0000-000000000001','21000000-0000-0000-0000-000000000001','inside-the-cpu','Inside the CPU','Meet the control unit, ALU, cache and registers.',9,1,'published'),
  ('30000000-0000-0000-0000-000000000002','21000000-0000-0000-0000-000000000001','fetch-decode-execute','Fetch, decode, execute','Follow one instruction through the processor cycle.',11,2,'published'),
  ('30000000-0000-0000-0000-000000000003','21000000-0000-0000-0000-000000000002','ram-rom-and-virtual-memory','RAM, ROM and virtual memory','Understand the different roles of primary memory.',12,1,'published'),
  ('30000000-0000-0000-0000-000000000004','21000000-0000-0000-0000-000000000002','secondary-storage','Secondary storage','Choose between magnetic, optical and solid-state storage.',13,2,'published'),
  ('30000000-0000-0000-0000-000000000005','21000000-0000-0000-0000-000000000003','network-foundations','Network foundations','Connect devices, compare network scales and understand topologies.',10,1,'published'),
  ('30000000-0000-0000-0000-000000000006','21000000-0000-0000-0000-000000000003','packets-and-protocols','Packets and protocols','See how data crosses a network and arrives in the right form.',12,2,'published')
insert into public.lesson_sections (id, lesson_id, heading, body, sort_order) values
  ('31000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','The computer''s instruction engine',$${"paragraphs":["The central processing unit (CPU) executes the instructions that make programs work. It repeatedly collects an instruction, works out what it means and carries it out.","A CPU is made from several specialised components. Each has a clear job, but they cooperate at very high speed."],"callout":{"type":"definition","title":"CPU","text":"The component that processes data and executes program instructions."}}$$::jsonb,1),
  ('31000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000001','Control unit and ALU',$${"paragraphs":["The control unit coordinates the CPU. It sends control signals, manages the flow of data and decodes each instruction.","The arithmetic logic unit (ALU) performs calculations and logical comparisons."],"callout":{"type":"tip","title":"Keep the jobs distinct","text":"The control unit organises; the ALU calculates and compares."}}$$::jsonb,2),
  ('31000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000001','Registers and cache',$${"paragraphs":["Registers are tiny, extremely fast storage locations inside the CPU. Named registers hold the current instruction, its address and intermediate data.","Cache stores frequently used instructions and data close to the CPU, reducing slower main-memory accesses."]}$$::jsonb,3),
  ('31000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000002','1. Fetch',$${"paragraphs":["The program counter stores the address of the next instruction. That address is copied to the memory address register.","The instruction is copied from memory into the memory data register, then the current instruction register. The program counter is incremented."]}$$::jsonb,1),
  ('31000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000002','2. Decode',$${"paragraphs":["The control unit interprets the instruction in the current instruction register. It identifies the operation and any data or address required."]}$$::jsonb,2),
  ('31000000-0000-0000-0000-000000000006','30000000-0000-0000-0000-000000000002','3. Execute',$${"paragraphs":["The instruction is carried out. This might involve an ALU calculation, moving data, testing a condition or changing the program counter."],"callout":{"type":"warning","title":"Common mix-up","text":"The cycle processes instructions, not entire programs in one go."}}$$::jsonb,3),
  ('31000000-0000-0000-0000-000000000007','30000000-0000-0000-0000-000000000003','RAM',$${"paragraphs":["Random access memory stores programs and data that are currently in use. It is volatile: its contents are lost when power is removed.","More RAM lets a computer keep more active data available without relying as heavily on slower secondary storage."],"callout":{"type":"definition","title":"Volatile","text":"Data is lost when the power is switched off."}}$$::jsonb,1),
  ('31000000-0000-0000-0000-000000000008','30000000-0000-0000-0000-000000000003','ROM',$${"paragraphs":["Read-only memory is non-volatile. It commonly stores startup instructions or firmware that must remain available when the device is switched off."]}$$::jsonb,2),
  ('31000000-0000-0000-0000-000000000009','30000000-0000-0000-0000-000000000003','Virtual memory',$${"paragraphs":["When RAM is full, the operating system can use part of secondary storage as virtual memory. Inactive pages are moved out of RAM to create space.","Secondary storage is much slower than RAM, so excessive virtual-memory use can make a system feel unresponsive."],"callout":{"type":"warning","title":"Not extra RAM","text":"Virtual memory provides extra capacity, but not RAM-level speed."}}$$::jsonb,3),
  ('31000000-0000-0000-0000-000000000010','30000000-0000-0000-0000-000000000004','Why secondary storage?',$${"paragraphs":["Secondary storage keeps programs and files when power is removed. It normally offers much greater capacity than primary memory at a lower cost per gigabyte."]}$$::jsonb,1),
  ('31000000-0000-0000-0000-000000000011','30000000-0000-0000-0000-000000000004','Three technologies',$${"paragraphs":["Magnetic storage offers high capacity at low cost but contains moving parts.","Optical discs are portable but have lower capacity and slower access.","Solid-state storage is fast, quiet and durable, but can cost more per gigabyte."]}$$::jsonb,2),
  ('31000000-0000-0000-0000-000000000012','30000000-0000-0000-0000-000000000004','Making a justified choice',$${"paragraphs":["A strong recommendation connects the situation to characteristics such as capacity, speed, portability, durability and cost."],"callout":{"type":"tip","title":"Exam technique","text":"Name the requirement, name the feature, then explain the connection."}}$$::jsonb,3),
  ('31000000-0000-0000-0000-000000000013','30000000-0000-0000-0000-000000000005','LANs and WANs',$${"paragraphs":["A local area network covers a small geographical area and is usually managed by one organisation. A wide area network connects networks across a larger area and often uses third-party infrastructure."],"callout":{"type":"definition","title":"Network","text":"Two or more connected devices that can communicate and share resources."}}$$::jsonb,1),
  ('31000000-0000-0000-0000-000000000014','30000000-0000-0000-0000-000000000005','Wired and wireless',$${"paragraphs":["Ethernet connections are typically reliable, secure and fast. Wireless connections provide mobility and are easier to extend, but signal strength and interference affect performance."]}$$::jsonb,2),
  ('31000000-0000-0000-0000-000000000015','30000000-0000-0000-0000-000000000005','Star topology',$${"paragraphs":["In a star network, each device has its own connection to a central switch. One failed cable normally affects only one device, but a failed switch can disrupt the whole network."]}$$::jsonb,3),
  ('31000000-0000-0000-0000-000000000016','30000000-0000-0000-0000-000000000006','Packet switching',$${"paragraphs":["Large messages are divided into packets. Each packet contains payload data plus control information such as source, destination and sequence number.","Packets may take different routes. The receiver reorders them and can request missing data."]}$$::jsonb,1),
  ('31000000-0000-0000-0000-000000000017','30000000-0000-0000-0000-000000000006','Why protocols matter',$${"paragraphs":["A protocol is an agreed set of rules for communication. Without shared rules, devices would disagree about the meaning, order or format of data."],"callout":{"type":"definition","title":"Protocol","text":"A standard set of rules that devices follow when communicating."}}$$::jsonb,2),
  ('31000000-0000-0000-0000-000000000018','30000000-0000-0000-0000-000000000006','Common examples',$${"paragraphs":["TCP checks reliable delivery and ordering. IP handles addressing and routing. HTTP and HTTPS transfer web content, while DNS converts domain names into IP addresses."],"callout":{"type":"tip","title":"TCP/IP is a suite","text":"TCP and IP cooperate but have different responsibilities."}}$$::jsonb,3)
insert into public.flashcards (id, subtopic_id, front, back, hint, sort_order, status) values
  ('40000000-0000-0000-0000-000000000001','21000000-0000-0000-0000-000000000001','What does the control unit do?','It coordinates CPU operations, decodes instructions and sends control signals.','Think organisation, not calculation.',1,'published'),
  ('40000000-0000-0000-0000-000000000002','21000000-0000-0000-0000-000000000001','Which register holds the address of the next instruction?','The program counter (PC).',null,2,'published'),
  ('40000000-0000-0000-0000-000000000003','21000000-0000-0000-0000-000000000001','Why can cache improve performance?','It keeps frequently used data and instructions close to the CPU, so they can be accessed faster than main memory.',null,3,'published'),
  ('40000000-0000-0000-0000-000000000004','21000000-0000-0000-0000-000000000002','What is the key difference between RAM and ROM?','RAM is volatile working memory; ROM is non-volatile and stores instructions that should persist.',null,1,'published'),
  ('40000000-0000-0000-0000-000000000005','21000000-0000-0000-0000-000000000002','Why does heavy virtual-memory use slow a computer?','It moves pages between RAM and slower secondary storage, creating extra read/write activity.',null,2,'published'),
  ('40000000-0000-0000-0000-000000000006','21000000-0000-0000-0000-000000000002','Give two advantages of solid-state storage.','Any two of: fast access, no moving parts, quiet, low power use, lightweight or durable.',null,3,'published'),
  ('40000000-0000-0000-0000-000000000007','21000000-0000-0000-0000-000000000003','What is stored in a packet header?','Control data such as source and destination addresses, a sequence number and error-checking information.',null,1,'published'),
  ('40000000-0000-0000-0000-000000000008','21000000-0000-0000-0000-000000000003','What is the role of DNS?','It resolves human-readable domain names to IP addresses.',null,2,'published'),
  ('40000000-0000-0000-0000-000000000009','21000000-0000-0000-0000-000000000003','How does HTTPS differ from HTTP?','HTTPS encrypts the connection and authenticates the server using TLS.',null,3,'published')
insert into public.worked_solutions (id, subtopic_id, title, prompt, steps, final_answer, status) values
  ('50000000-0000-0000-0000-000000000001','21000000-0000-0000-0000-000000000001','Comparing CPU performance','Computer A has four 2.8 GHz cores and 4 MB of cache. Computer B has two 3.2 GHz cores and 12 MB of cache. Explain why the specifications alone do not prove which computer will run every program faster. [4 marks]',$$[{"title":"Identify relevant factors","explanation":"Clock speed, core count and cache size can all affect performance.","working":"A: more cores · B: faster clock + larger cache"},{"title":"Explain the trade-off","explanation":"More cores help software that can divide work into parallel tasks. Clock speed and cache affect other workloads."},{"title":"Add the missing context","explanation":"Programs use hardware differently, and performance also depends on processor design."}]$$::jsonb,'Computer A may perform better on programs that split work across four cores. Computer B completes more clock cycles per second and its larger cache may reduce main-memory access. However, programs use cores and cache differently, and processor architecture also matters, so these figures cannot prove one computer is always faster.','published'),
  ('50000000-0000-0000-0000-000000000002','21000000-0000-0000-0000-000000000002','Choosing portable storage','A wildlife photographer needs storage for thousands of large images while working outdoors. Recommend a storage technology and justify your choice. [3 marks]',$$[{"title":"Extract the needs","explanation":"The device needs high capacity for large files and durability for outdoor use."},{"title":"Choose a technology","explanation":"Solid-state storage is available in high capacities and has no fragile moving parts."},{"title":"Link features to context","explanation":"Explain why each feature matters to this photographer rather than listing generic advantages."}]$$::jsonb,'Use a high-capacity solid-state drive. It can store thousands of large image files and has no moving parts, making it more resistant to knocks while the photographer works outdoors. Its fast transfer speed also helps when saving or reviewing many large photographs.','published'),
  ('50000000-0000-0000-0000-000000000003','21000000-0000-0000-0000-000000000003','Explaining packet switching','Explain how a large file is transferred across the internet using packet switching. [4 marks]',$$[{"title":"Start with division","explanation":"The file is divided into smaller packets with addressing and ordering data."},{"title":"Describe the journey","explanation":"Routers forward packets and they may travel along different available routes."},{"title":"Finish at the receiver","explanation":"Sequence numbers restore the order, and missing or corrupt packets can be requested again."}]$$::jsonb,'The file is split into packets, each with destination and sequence information in its header. Routers forward the packets, and different packets may take different available routes. At the destination, sequence numbers are used to reassemble the file in the correct order. Missing or damaged packets are retransmitted.','published')
